package week_09.data_structures.class_problems;
public class WarehouseBinGridScan {static class Summary{long total;int row,col,max;Summary(long t,int r,int c,int m){total=t;row=r;col=c;max=m;}public String toString(){return "total="+total+", maxCoordinate=("+row+", "+col+"), maxValue="+max;}}public static Summary warehouseSummary(int[][]g){if(g==null||g.length==0||g[0].length==0)throw new IllegalArgumentException("Grid empty");long sum=0;int max=-1,r0=0,c0=0;for(int r=0;r<g.length;r++){if(g[r]==null||g[r].length!=g[0].length)throw new IllegalArgumentException("Ragged grid");for(int c=0;c<g[r].length;c++){if(g[r][c]<0)throw new IllegalArgumentException("Negative bin count");sum+=g[r][c];if(g[r][c]>max){max=g[r][c];r0=r;c0=c;}}}return new Summary(sum,r0,c0,max);}public static void main(String[]a){System.out.println(warehouseSummary(new int[][]{{4,9,2},{7,1,6},{3,12,5}}));}}